/* tzlookup implementation. The data tables are generated by build/emit_c.py. */
#include "tzlookup.h"

#include <cctype>

#include "tz_data.h"  /* TZ_ZONES, TZ_ZIP_ZONE, TZ_NPA_ZONE, TZ_*_MAX */

static const char *zone_name(unsigned idx) {
  /* idx 0 is the "" unknown slot; treat it as not-found. */
  return idx ? TZ_ZONES[idx] : nullptr;
}

const char *tz_from_zip(int zip) {
  if (zip < 0 || zip >= TZ_ZIP_MAX) return nullptr;
  return zone_name(TZ_ZIP_ZONE[zip]);
}

const char *tz_from_areacode(int npa) {
  if (npa < 0 || npa >= TZ_NPA_MAX) return nullptr;
  return zone_name(TZ_NPA_ZONE[npa]);
}

const char *tz_lookup_codes(int zip, int npa) {
  const char *z = tz_from_zip(zip);
  if (z) return z;
  return tz_from_areacode(npa);
}

int tz_parse_zip(const char *s) {
  if (!s) return -1;
  /* Take the first run of up to 5 digits; ignore a trailing +4 or formatting. */
  int val = 0, n = 0;
  while (*s && !std::isdigit((unsigned char)*s)) ++s;  /* skip leading junk */
  while (*s && std::isdigit((unsigned char)*s) && n < 5) {
    val = val * 10 + (*s - '0');
    ++s;
    ++n;
  }
  return n == 5 ? val : -1;
}

int tz_parse_areacode(const char *phone) {
  if (!phone) return -1;
  /* Collect digits; drop a leading NANP country code '1' if 11 digits. */
  char d[16];
  int n = 0;
  for (const char *p = phone; *p && n < 15; ++p)
    if (std::isdigit((unsigned char)*p)) d[n++] = *p;
  d[n] = '\0';

  const char *npa = d;
  if (n == 11 && d[0] == '1') npa = d + 1;  /* 1-NPA-NXX-XXXX */
  else if (n == 7) return -1;               /* NXX-XXXX, no area code */
  else if (n < 10) return -1;

  /* NANP area codes are 2xx-9xx (first digit 2..9). */
  if (npa[0] < '2' || npa[0] > '9') return -1;
  return (npa[0] - '0') * 100 + (npa[1] - '0') * 10 + (npa[2] - '0');
}

const char *tz_lookup(const char *zip_str, const char *phone_str) {
  return tz_lookup_codes(tz_parse_zip(zip_str), tz_parse_areacode(phone_str));
}
